import sys

def search_nearly_sorted(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        if arr[mid] < target:
            if mid + 1 <= right and arr[mid + 1] == target:
                return mid + 1
            if mid - 1 >= left and arr[mid - 1] == target:
                return mid - 1
            left = mid + 2
            right = right
        else:
            if mid + 1 <= right and arr[mid + 1] == target:
                return mid + 1
            if mid - 1 >= left and arr[mid - 1] == target:
                return mid - 1
            right = mid - 2

    return -1

def main():
    line1 = sys.stdin.readline()
    if not line1:
        print(-1)
        return

    arr = list(map(int, line1.strip().split()))

    line2 = sys.stdin.readline()
    if not line2:
        print(-1)
        return

    target = int(line2.strip())

    result = search_nearly_sorted(arr, target)
    print(result)

if __name__ == "__main__":
    main()
